namespace UniversityOS.Domain

open System

/// A flashcard / revision question, usually generated by the AI from notes,
/// lecture transcripts or documents.
type RevisionItem =
    { Id: RevisionItemId
      ModuleId: ModuleId option
      Question: string
      Answer: string
      /// Where this card came from (a note, a lecture, a document).
      Source: EntityRef option
      CreatedAt: DateTime }

[<RequireQualifiedAccess>]
module RevisionItem =

    let create (now: DateTime) (question: string) (answer: string) =
        { Id = RevisionItemId.New()
          ModuleId = None
          Question = question.Trim()
          Answer = answer.Trim()
          Source = None
          CreatedAt = now }
